package com.habitpro.controller;import com.habitpro.model.Habit;import com.habitpro.repository.HabitRepository;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/habits") public class HabitController{private final HabitRepository repo;public HabitController(HabitRepository r){repo=r;}public record HabitInput(String name,String category){}@GetMapping public List<Habit> all(Authentication a){return repo.findByUserId(a.getName());}@PostMapping public ResponseEntity<?> add(@RequestBody HabitInput in,Authentication a){if(in.name()==null||in.name().trim().length()<2)return ResponseEntity.badRequest().body(Map.of("message","Habit name must contain at least 2 characters"));Habit h=new Habit();h.setName(in.name().trim());h.setCategory(in.category()==null||in.category().isBlank()?"General":in.category().trim());h.setUserId(a.getName());return ResponseEntity.ok(repo.save(h));}@PostMapping("/{id}/complete")public ResponseEntity<?> complete(@PathVariable String id,Authentication a){var opt=repo.findByIdAndUserId(id,a.getName());if(opt.isEmpty())return ResponseEntity.notFound().build();Habit h=opt.get();String d=LocalDate.now().toString();if(h.getCompletedDates().contains(d))return ResponseEntity.badRequest().body(Map.of("message","Habit already completed today"));h.getCompletedDates().add(d);h.setStreak(h.getStreak()+1);return ResponseEntity.ok(repo.save(h));}@DeleteMapping("/{id}")public ResponseEntity<?> delete(@PathVariable String id,Authentication a){var h=repo.findByIdAndUserId(id,a.getName());if(h.isEmpty())return ResponseEntity.notFound().build();repo.delete(h.get());return ResponseEntity.noContent().build();}}